export default function ContactsClient({ initialContacts, backendReady }: { initialContacts: Contact[]; backendReady: boolean }) {
 const supabase=useMemo(()=>createClient(),[]); const [contacts,setContacts]=useState(initialContacts); const [matches,setMatches]=useState<DiscoveryMatch[]>([]); const [message,setMessage]=useState(backendReady?"":"Η βάση επαφών δεν είναι ακόμη διαθέσιμη στο production."); const [busy,setBusy]=useState(false);
 async function refresh(){const {data}=await supabase.from("contacts").select("id,display_name,email,phone,linked_user_id,source_external_id,created_at").order("display_name"); if(data)setContacts(data as Contact[]);}
 async function addManual(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setMessage("");const form=new FormData(event.currentTarget);const {error}=await supabase.rpc("pantavion_add_manual_contact",{p_display_name:String(form.get("name")||"").trim()||null,p_email:String(form.get("email")||"").trim()||null,p_phone:String(form.get("phone")||"").trim()||null});setBusy(false);if(error)return setMessage(error.message);event.currentTarget.reset();await refresh();}
 async function importFile(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file)return;setBusy(true);setMessage("");try{const text=await file.text();const isVcard=file.name.toLowerCase().endsWith(".vcf");const parsed=isVcard?parseVCard(text):parseCsv(text);if(!parsed.length){setMessage("Δεν βρέθηκαν επαφές στο αρχείο.");return;}const {data,error}=await supabase.rpc("pantavion_import_contacts_batch",{p_source_type:isVcard?"vcard":"csv",p_filename:file.name,p_contacts:parsed});if(error){setMessage(error.message);return;}setMessage(`Μεταφέρθηκαν ${Number(data??0)} επαφές.`);event.target.value="";await refresh();}finally{setBusy(false);}}
 async function findMyPeople(){if(!contacts.length||busy)return;setBusy(true);setMessage("");setMatches([]);try{const response=await fetch("/api/people/find-from-contacts",{method:"POST"});const json=await response.json().catch(()=>({}));if(!response.ok){setMessage(json.detail||"Δεν ολοκληρώθηκε η αναζήτηση.");return;}const found=(json.matches??[]) as DiscoveryMatch[];setMatches(found);setMessage(found.length?`Βρέθηκαν ${found.length} επαφές που είναι ήδη στο Pantavion.`:"Δεν βρέθηκε ακόμη κάποια από αυτές τις επαφές στο Pantavion.");}finally{setBusy(false);}}
 return <div className="grid gap-5 lg:grid-cols-[340px_1fr]">
  <aside className="rounded-[1.4rem] border border-slate-200 bg-white p-5 shadow-sm"><h2 className="text-xl font-black text-[#173f72]">Προσθήκη επαφών</h2><form className="mt-4 space-y-3" onSubmit={addManual}><input name="name" placeholder="Όνομα" className="w-full rounded-xl border border-slate-200 px-3 py-2.5"/><input name="email" type="email" placeholder="Email" className="w-full rounded-xl border border-slate-200 px-3 py-2.5"/><input name="phone" placeholder="Τηλέφωνο" className="w-full rounded-xl border border-slate-200 px-3 py-2.5"/><button disabled={busy||!backendReady} className="w-full rounded-full bg-[#2467aa] px-4 py-2.5 text-sm font-black text-white disabled:opacity-40">Προσθήκη</button></form><div className="my-5 h-px bg-slate-100"/><label className="block text-sm font-black text-slate-700">Μεταφορά από αρχείο</label><p className="mt-1 text-xs leading-5 text-slate-500">vCard (.vcf) ή CSV που έχεις εξαγάγει εσύ από συσκευή ή υπηρεσία.</p><input className="mt-3 block w-full text-xs" type="file" accept=".vcf,.csv,text/vcard,text/csv" disabled={busy||!backendReady} onChange={importFile}/><div className="my-5 h-px bg-slate-100"/><h3 className="text-sm font-black text-slate-800">Βρες τους ανθρώπους σου</h3><p className="mt-1 text-xs leading-5 text-slate-500">Με δική σου επιλογή γίνεται ιδιωτικό matching. Δεν εμφανίζονται email ή τηλέφωνα άλλων χρηστών.</p><button type="button" disabled={busy||!backendReady||!contacts.length} onClick={findMyPeople} className="mt-3 w-full rounded-full bg-[#123b67] px-4 py-2.5 text-sm font

